  1	package com.mareaalta.service;
  2	
  3	import java.time.LocalDate;
  4	import java.time.format.DateTimeFormatter;
  5	import java.math.BigDecimal;
  6	import java.math.RoundingMode;
  7	
  8	public class PricingService {
  9	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 10	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
 11	
 12	    public static double roundToTwoCents(double value) {
 13	        return new BigDecimal(value).setScale(2, ROUNDING_MODE).doubleValue();
 14	    }
 15	
 16	    public static boolean isHighSeason(LocalDate date) {
 17	        int month = date.getMonthValue();
 18	        int day = date.getDayOfMonth();
 19	
 20	        if (month == 7) return true;
 21	        if (month == 12 && day >= 15) return true;
 22	        if (month >= 1 && month <= 2) return true;
 23	
 24	        return false;
 25	    }
 26	
 27	    public static int calculateNights(String checkInStr, String checkOutStr) {
 28	        LocalDate checkIn = LocalDate.parse(checkInStr, DATE_FORMAT);
 29	        LocalDate checkOut = LocalDate.parse(checkOutStr, DATE_FORMAT);
 30	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
 31	    }
 32	
 33	    public static PricingResult calculatePrice(String ratePlan, int nights, double nightlyRate, String checkIn, String checkOut, String companyCode) {
 34	        return switch (ratePlan) {
 35	            case "STANDARD" -> calculateStandard(nights, nightlyRate, checkIn);
 36	            case "NON_REFUNDABLE" -> calculateNonRefundable(nights, nightlyRate, checkIn);
 37	            case "CORPORATE" -> calculateCorporate(nights, nightlyRate, checkIn, companyCode);
 38	            case "WEEKEND_PACKAGE" -> calculateWeekendPackage(nights, nightlyRate, checkIn, checkOut);
 39	            case "LONG_STAY" -> calculateLongStay(nights, nightlyRate, checkIn);
 40	            default -> null;
 41	        };
 42	    }
 43	
 44	    private static PricingResult calculateStandard(int nights, double nightlyRate, String checkIn) {
 45	        LocalDate checkInDate = LocalDate.parse(checkIn, DATE_FORMAT);
 46	        double subtotal = 0;
 47	        for (int i = 0; i < nights; i++) {
 48	            LocalDate date = checkInDate.plusDays(i);
 49	            double rate = nightlyRate;
 50	            if (isHighSeason(date)) {
 51	                rate = roundToTwoCents(rate * 1.2);
 52	            } else {
 53	                rate = roundToTwoCents(rate);
 54	            }
 55	            subtotal = roundToTwoCents(subtotal + rate);
 56	        }
 57	        return new PricingResult(subtotal, 0, subtotal);
 58	    }
 59	
 60	    private static PricingResult calculateNonRefundable(int nights, double nightlyRate, String checkIn) {
 61	        LocalDate checkInDate = LocalDate.parse(checkIn, DATE_FORMAT);
 62	        double subtotal = 0;
 63	        for (int i = 0; i < nights; i++) {
 64	            LocalDate date = checkInDate.plusDays(i);
 65	            double rate = nightlyRate;
 66	            if (isHighSeason(date)) {
 67	                rate = roundToTwoCents(rate * 1.2);
 68	            } else {
 69	                rate = roundToTwoCents(rate);
 70	            }
 71	            subtotal = roundToTwoCents(subtotal + rate);
 72	        }
 73	        double discount = roundToTwoCents(subtotal * 0.15);
 74	        double total = roundToTwoCents(subtotal - discount);
 75	        return new PricingResult(subtotal, discount, total);
 76	    }
 77	
 78	    private static PricingResult calculateCorporate(int nights, double nightlyRate, String checkIn, String companyCode) {
 79	        double discountRate = getCompanyDiscountRate(companyCode);
 80	        if (discountRate < 0) return null;
 81	
 82	        LocalDate checkInDate = LocalDate.parse(checkIn, DATE_FORMAT);
 83	        double subtotal = 0;
 84	        for (int i = 0; i < nights; i++) {
 85	            LocalDate date = checkInDate.plusDays(i);
 86	            double rate = nightlyRate;
 87	            if (isHighSeason(date)) {
 88	                rate = roundToTwoCents(rate * 1.2);
 89	            } else {
 90	                rate = roundToTwoCents(rate);
 91	            }
 92	            subtotal = roundToTwoCents(subtotal + rate);
 93	        }
 94	        double discount = roundToTwoCents(subtotal * discountRate);
 95	        double total = roundToTwoCents(subtotal - discount);
 96	        return new PricingResult(subtotal, discount, total);
 97	    }
 98	
 99	    private static PricingResult calculateWeekendPackage(int nights, double nightlyRate, String checkIn, String checkOut) {
100	        LocalDate checkInDate = LocalDate.parse(checkIn, DATE_FORMAT);
101	        LocalDate checkOutDate = LocalDate.parse(checkOut, DATE_FORMAT);
102	
103	        int actualNights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkInDate, checkOutDate);
104	        if (actualNights != 2) return null;
105	
106	        if (checkInDate.getDayOfWeek() != java.time.DayOfWeek.FRIDAY) return null;
107	        if (checkOutDate.getDayOfWeek() != java.time.DayOfWeek.SUNDAY) return null;
108	
109	        double packagePrice = getWeekendPackagePrice(nightlyRate);
110	        if (packagePrice < 0) return null;
111	
112	        return new PricingResult(packagePrice, 0, packagePrice);
113	    }
114	
115	    private static double getWeekendPackagePrice(double nightlyRate) {
116	        double rounded = Math.round(nightlyRate * 100.0) / 100.0;
117	        if (rounded == 249.90) return 520.00;
118	        if (rounded == 389.90) return 820.00;
119	        if (rounded == 579.90) return 1200.00;
120	        return -1;
121	    }
122	
123	    private static PricingResult calculateLongStay(int nights, double nightlyRate, String checkIn) {
124	        if (nights < 7) return null;
125	
126	        LocalDate checkInDate = LocalDate.parse(checkIn, DATE_FORMAT);
127	        double subtotal = 0;
128	        for (int i = 0; i < nights; i++) {
129	            LocalDate date = checkInDate.plusDays(i);
130	            double rate = nightlyRate;
131	            if (isHighSeason(date)) {
132	                rate = roundToTwoCents(rate * 1.2);
133	            } else {
134	                rate = roundToTwoCents(rate);
135	            }
136	            subtotal = roundToTwoCents(subtotal + rate);
137	        }
138	        double discount = roundToTwoCents(subtotal * 0.10);
139	        double total = roundToTwoCents(subtotal - discount);
140	        return new PricingResult(subtotal, discount, total);
141	    }
142	
143	    private static double getCompanyDiscountRate(String companyCode) {
144	        return switch (companyCode) {
145	            case "TECNOSUL" -> 0.12;
146	            case "AGROVALE" -> 0.18;
147	            case "FARMAVIDA" -> 0.25;
148	            default -> -1;
149	        };
150	    }
151	
152	    public static class PricingResult {
153	        public double subtotal;
154	        public double discount;
155	        public double total;
156	
157	        public PricingResult(double subtotal, double discount, double total) {
158	            this.subtotal = subtotal;
159	            this.discount = discount;
160	            this.total = total;
161	        }
162	    }
163	}
164	package com.mareaalta.service;
165	
166	import com.mareaalta.model.Reservation;
167	import com.mareaalta.model.Room;
168	import com.mareaalta.data.RoomData;
169	import java.time.LocalDate;
170	import java.time.format.DateTimeFormatter;
171	import java.util.*;
172	import java.math.BigDecimal;
173	import java.math.RoundingMode;
174	
175	public class ReservationService {
176	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
177	    private Map<Integer, Reservation> reservations = new HashMap<>();
178	    private int nextId = 1;
179	
180	    public ReservationService() {}
181	
182	    public Room getRoomByNumber(int roomNumber) {
183	        return RoomData.getRooms().stream()
184	            .filter(r -> r.number() == roomNumber)
185	            .findFirst()
186	            .orElse(null);
187	    }
188	
189	    public List<Room> getAllRooms() {
190	        return RoomData.getRooms();
191	    }
192	
193	    public String validateCreateReservation(int roomNumber, String checkIn, String checkOut, int guests, String ratePlan, String companyCode) {
194	        if (!isValidDateFormat(checkIn) || !isValidDateFormat(checkOut)) {
195	            return "INVALID_REQUEST";
196	        }
197	
198	        LocalDate checkInDate = LocalDate.parse(checkIn, DATE_FORMAT);
199	        LocalDate checkOutDate = LocalDate.parse(checkOut, DATE_FORMAT);
200	
201	        if (!checkOutDate.isAfter(checkInDate)) {
202	            return "INVALID_REQUEST";
203	        }
204	
205	        if (guests < 1) {
206	            return "INVALID_REQUEST";
207	        }
208	
209	        Room room = getRoomByNumber(roomNumber);
210	        if (room == null) {
211	            return "ROOM_NOT_FOUND";
212	        }
213	
214	        if (guests > room.capacity()) {
215	            return "CAPACITY_EXCEEDED";
216	        }
217	
218	        if (!isRatePlanValid(ratePlan, checkIn, checkOut, companyCode)) {
219	            return "INVALID_REQUEST";
220	        }
221	
222	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
223	            return "ROOM_UNAVAILABLE";
224	        }
225	
226	        return null;
227	    }
228	
229	    private boolean isRatePlanValid(String ratePlan, String checkIn, String checkOut, String companyCode) {
230	        return switch (ratePlan) {
231	            case "STANDARD", "NON_REFUNDABLE" -> true;
232	            case "LONG_STAY" -> isValidLongStay(checkIn, checkOut);
233	            case "CORPORATE" -> companyCode != null && isValidCompanyCode(companyCode);
234	            case "WEEKEND_PACKAGE" -> isValidWeekendPackage(checkIn, checkOut);
235	            default -> false;
236	        };
237	    }
238	
239	    private boolean isValidLongStay(String checkIn, String checkOut) {
240	        try {
241	            int nights = PricingService.calculateNights(checkIn, checkOut);
242	            return nights >= 7;
243	        } catch (Exception e) {
244	            return false;
245	        }
246	    }
247	
248	    private boolean isValidCompanyCode(String code) {
249	        return code.equals("TECNOSUL") || code.equals("AGROVALE") || code.equals("FARMAVIDA");
250	    }
251	
252	    private boolean isValidWeekendPackage(String checkIn, String checkOut) {
253	        try {
254	            LocalDate checkInDate = LocalDate.parse(checkIn, DATE_FORMAT);
255	            LocalDate checkOutDate = LocalDate.parse(checkOut, DATE_FORMAT);
256	
257	            int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkInDate, checkOutDate);
258	            if (nights != 2) return false;
259	
260	            if (checkInDate.getDayOfWeek() != java.time.DayOfWeek.FRIDAY) return false;
261	            if (checkOutDate.getDayOfWeek() != java.time.DayOfWeek.SUNDAY) return false;
262	
263	            return true;
264	        } catch (Exception e) {
265	            return false;
266	        }
267	    }
268	
269	    private boolean isValidDateFormat(String date) {
270	        try {
271	            LocalDate.parse(date, DATE_FORMAT);
272	            return true;
273	        } catch (Exception e) {
274	            return false;
275	        }
276	    }
277	
278	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
279	                                        String checkIn, String checkOut, int guests, String ratePlan, String companyCode) {
280	        int id = nextId++;
281	        Reservation res = new Reservation(id, roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan, companyCode);
282	
283	        int nights = PricingService.calculateNights(checkIn, checkOut);
284	        res.nights = nights;
285	
286	        Room room = getRoomByNumber(roomNumber);
287	        PricingService.PricingResult pricing = PricingService.calculatePrice(ratePlan, nights, room.nightlyRate(), checkIn, checkOut, companyCode);
288	
289	        if (pricing != null) {
290	            res.subtotal = pricing.subtotal;
291	            res.discount = pricing.discount;
292	            res.total = pricing.total;
293	        }
294	
295	        reservations.put(id, res);
296	        return res;
297	    }
298	
299	    public Reservation getReservation(int id) {
300	        return reservations.get(id);
301	    }
302	
303	    private boolean isRoomUnavailable(int roomNumber, String checkIn, String checkOut) {
304	        LocalDate checkInDate = LocalDate.parse(checkIn, DATE_FORMAT);
305	        LocalDate checkOutDate = LocalDate.parse(checkOut, DATE_FORMAT);
306	
307	        for (Reservation res : reservations.values()) {
308	            if (res.roomNumber == roomNumber && !res.status.equals("CANCELLED")) {
309	                LocalDate resCheckIn = LocalDate.parse(res.checkIn, DATE_FORMAT);
310	                LocalDate resCheckOut = LocalDate.parse(res.checkOut, DATE_FORMAT);
311	
312	                if (checkInDate.isBefore(resCheckOut) && checkOutDate.isAfter(resCheckIn)) {
313	                    return true;
314	                }
315	            }
316	        }
317	        return false;
318	    }
319	
320	    public String confirmReservation(int id) {
321	        Reservation res = getReservation(id);
322	        if (res == null) {
323	            return "RESERVATION_NOT_FOUND";
324	        }
325	        if (!res.status.equals("PENDING")) {
326	            return "OPERATION_NOT_ALLOWED";
327	        }
328	        res.status = "CONFIRMED";
329	        res.amountPaid = res.total;
330	        return null;
331	    }
332	
333	    public String cancelReservation(int id) {
334	        Reservation res = getReservation(id);
335	        if (res == null) {
336	            return "RESERVATION_NOT_FOUND";
337	        }
338	        if (!res.status.equals("PENDING") && !res.status.equals("CONFIRMED")) {
339	            return "OPERATION_NOT_ALLOWED";
340	        }
341	
342	        res.status = "CANCELLED";
343	
344	        if (res.amountPaid > 0) {
345	            double refundAmount = calculateRefund(res);
346	            res.refund = PricingService.roundToTwoCents(refundAmount);
347	        } else {
348	            res.refund = 0.0;
349	        }
350	
351	        return null;
352	    }
353	
354	    private double calculateRefund(Reservation res) {
355	        return switch (res.ratePlan) {
356	            case "STANDARD", "CORPORATE", "LONG_STAY" -> res.amountPaid;
357	            case "NON_REFUNDABLE" -> 0;
358	            case "WEEKEND_PACKAGE" -> PricingService.roundToTwoCents(res.amountPaid * 0.5);
359	            default -> 0;
360	        };
361	    }
362	
363	    public String checkIn(int id) {
364	        Reservation res = getReservation(id);
365	        if (res == null) {
366	            return "RESERVATION_NOT_FOUND";
367	        }
368	        if (!res.status.equals("CONFIRMED")) {
369	            return "OPERATION_NOT_ALLOWED";
370	        }
371	        res.status = "CHECKED_IN";
372	        return null;
373	    }
374	
375	    public String checkOut(int id) {
376	        Reservation res = getReservation(id);
377	        if (res == null) {
378	            return "RESERVATION_NOT_FOUND";
379	        }
380	        if (!res.status.equals("CHECKED_IN")) {
381	            return "OPERATION_NOT_ALLOWED";
382	        }
383	        res.status = "CHECKED_OUT";
384	        return null;
385	    }
386	
387	    public Collection<Reservation> getAllReservations() {
388	        return reservations.values();
389	    }
390	}
