446	
447	    public Reservation() {}
448	
449	    public Reservation(int id, int roomNumber, String guestName, String guestEmail, String guestCpf,
450	                      String checkIn, String checkOut, int guests, String ratePlan, String companyCode) {
451	        this.id = id;
452	        this.roomNumber = roomNumber;
453	        this.guestName = guestName;
454	        this.guestEmail = guestEmail;
455	        this.guestCpf = guestCpf;
456	        this.checkIn = checkIn;
457	        this.checkOut = checkOut;
458	        this.guests = guests;
459	        this.ratePlan = ratePlan;
460	        this.companyCode = companyCode;
461	        this.status = "PENDING";
462	        this.amountPaid = 0;
463	        this.refund = null;
464	    }
465	}

