 27	            try {
 28	                var body = ctx.bodyAsClass(ReservationRequest.class);
 29	
 30	                String validationError = reservationService.validateCreateReservation(
 31	                    body.roomNumber,
 32	                    body.checkIn,
 33	                    body.checkOut,
 34	                    body.guests,
 35	                    body.ratePlan,
