227	    private static int getStatusCode(String error) {
228	        return switch (error) {
229	            case "ROOM_NOT_FOUND", "RESERVATION_NOT_FOUND" -> 404;
230	            case "ROOM_UNAVAILABLE", "OPERATION_NOT_ALLOWED" -> 409;
231	            case "CAPACITY_EXCEEDED" -> 422;
232	            default -> 400;
233	        };
234	    }
235	
236	    private static String getMessage(String error) {
237	        return switch (error) {
238	            case "INVALID_REQUEST" -> "Invalid request";
239	            case "ROOM_NOT_FOUND" -> "Room not found";
240	            case "RESERVATION_NOT_FOUND" -> "Reservation not found";
241	            case "ROOM_UNAVAILABLE" -> "Room is not available for the selected dates";
242	            case "OPERATION_NOT_ALLOWED" -> "Operation not allowed for this reservation status";
243	            case "CAPACITY_EXCEEDED" -> "Number of guests exceeds room capacity";
244	            default -> "Unknown error";
245	        };
246	    }
