248	    private static void sendConfirmationEmail(Reservation reservation) {
249	        Room room = reservationService.getRoomByNumber(reservation.roomNumber);
250	        Receipt receipt = generateReceipt(reservation);
251	        String receiptText = formatReceipt(receipt);
252	
253	        String emailBody = "Olá, " + reservation.guestName + "!\n\n"
254	            + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
255	            + receiptText
256	            + "\n\nA entrada é a partir das 14h, e a saída, até as 12h.\n"
257	            + "Até breve!";
258	
259	        messageService.sendEmail(
260	            reservation.guestEmail,
261	            "Reserva confirmada - Pousada Maré Alta",
262	            emailBody
263	        );
264	    }
265	
266	    private static Receipt generateReceipt(Reservation reservation) {
267	        Room room = reservationService.getRoomByNumber(reservation.roomNumber);
268	        return new Receipt(
269	            reservation.id,
270	            reservation.guestName,
271	            reservation.guestCpf,
272	            reservation.roomNumber,
273	            room.type(),
274	            reservation.checkIn,
275	            reservation.checkOut,
276	            reservation.nights,
277	            reservation.subtotal,
278	            reservation.discount,
279	            reservation.total
280	        );
281	    }
282	
283	    private static String formatReceipt(Receipt receipt) {
284	        String nights = receipt.nights == 1 ? "1 diária" : receipt.nights + " diárias";
285	        String subtotalStr = String.format("R$ %.2f", receipt.subtotal).replace(".", ",");
286	        String discountStr = String.format("R$ %.2f", receipt.discount).replace(".", ",");
287	        String totalStr = String.format("R$ %.2f", receipt.total).replace(".", ",");
288	
289	        StringBuilder sb = new StringBuilder();
290	        sb.append("Comprovante de reserva nº ").append(receipt.reservationId).append("\n");
291	        sb.append("Hóspede: ").append(receipt.guestName).append(" (CPF ").append(receipt.guestCpf).append(")\n");
292	        sb.append("Quarto: ").append(receipt.roomNumber).append(" (").append(receipt.roomType).append(")\n");
293	        sb.append("Entrada: ").append(formatDateForReceipt(receipt.checkIn)).append(" | ");
294	        sb.append("Saída: ").append(formatDateForReceipt(receipt.checkOut)).append(" | ");
295	        sb.append(nights).append("\n");
296	        sb.append("Diárias: ").append(subtotalStr).append("\n");
297	
298	        if (receipt.discount > 0) {
299	            sb.append("Desconto: ").append(discountStr).append("\n");
300	        }
301	
302	        sb.append("Total: ").append(totalStr);
303	
304	        return sb.toString();
305	    }
306	
307	    private static String formatDateForReceipt(String dateStr) {
308	        LocalDate date = LocalDate.parse(dateStr, DATE_FORMAT);
309	        return date.format(DateTimeFormatter.ofPattern("dd/MM/yyyy"));
310	    }
