 34	    private static final DateTimeFormatter CSV_DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 35	    private static final DateTimeFormatter CSV_MONEY_FORMAT = DateTimeFormatter.ofPattern("0.00");
 36	
 37	    public String generateOccupancyReport(String dateStr, Collection<Reservation> reservations) {
 38	        try {
 39	            LocalDate date = LocalDate.parse(dateStr, DATE_FORMAT);
 40	            StringBuilder csv = new StringBuilder();
 41	            csv.append("room,type,reservation,check_in,check_out\n");
 42	
 43	            List<Reservation> occupiedRooms = new ArrayList<>();
 44	            for (Reservation res : reservations) {
 45	                if (res.status.equals("CANCELLED")) continue;
 46	                if (!isConfirmedOrLater(res)) continue;
 47	
 48	                LocalDate checkIn = LocalDate.parse(res.checkIn, DATE_FORMAT);
 49	                LocalDate checkOut = LocalDate.parse(res.checkOut, DATE_FORMAT);
 50	
 51	                if (!date.isBefore(checkIn) && date.isBefore(checkOut)) {
 52	                    occupiedRooms.add(res);
 53	                }
 54	            }
 55	
 56	            occupiedRooms.sort(Comparator.comparingInt(r -> r.roomNumber));
 57	
 58	            int totalOccupied = 0;
 59	            for (Reservation res : occupiedRooms) {
 60	                Room room = RoomData.getRooms().stream()
 61	                    .filter(r -> r.number() == res.roomNumber)
 62	                    .findFirst()
 63	                    .orElse(null);
 64	                if (room != null) {
 65	                    csv.append(res.roomNumber).append(",")
 66	                        .append(room.type()).append(",")
 67	                        .append(res.id).append(",")
 68	                        .append(res.checkIn).append(",")
 69	                        .append(res.checkOut).append("\n");
 70	                    totalOccupied++;
 71	                }
 72	            }
 73	
 74	            csv.append("total,").append(totalOccupied).append("/5\n");
 75	            return csv.toString();
 76	        } catch (Exception e) {
 77	            return null;
 78	        }
 79	    }
