 85	    public String generateRevenueReport(String monthStr, Collection<Reservation> reservations) {
 86	        try {
 87	            YearMonth month = YearMonth.parse(monthStr);
 88	            StringBuilder csv = new StringBuilder();
 89	            csv.append("reservation,room,check_in,check_out,status,amount\n");
 90	
 91	            List<Reservation> monthReservations = new ArrayList<>();
 92	            for (Reservation res : reservations) {
 93	                LocalDate checkIn = LocalDate.parse(res.checkIn, DATE_FORMAT);
 94	                if (YearMonth.from(checkIn).equals(month)) {
 95	                    double amount = calculateAmountForRevenue(res);
 96	                    if (amount > 0) {
 97	                        monthReservations.add(res);
 98	                    }
 99	                }
100	            }
101	
102	            monthReservations.sort((r1, r2) -> {
103	                LocalDate d1 = LocalDate.parse(r1.checkIn, DATE_FORMAT);
104	                LocalDate d2 = LocalDate.parse(r2.checkIn, DATE_FORMAT);
105	                int dateCompare = d1.compareTo(d2);
106	                if (dateCompare != 0) return dateCompare;
107	                return Integer.compare(r1.id, r2.id);
108	            });
109	
110	            double totalAmount = 0;
111	            for (Reservation res : monthReservations) {
112	                double amount = calculateAmountForRevenue(res);
113	                csv.append(res.id).append(",")
114	                    .append(res.roomNumber).append(",")
115	                    .append(res.checkIn).append(",")
116	                    .append(res.checkOut).append(",")
117	                    .append(res.status).append(",")
118	                    .append(formatMoney(amount)).append("\n");
119	                totalAmount += amount;
120	            }
121	
122	            csv.append("total,,,,").append(formatMoney(totalAmount)).append("\n");
123	            return csv.toString();
124	        } catch (Exception e) {
125	            return null;
126	        }
127	    }
128	
129	    private double calculateAmountForRevenue(Reservation res) {
130	        double paid = res.amountPaid;
131	        double refunded = res.refund != null ? res.refund : 0;
132	        return paid - refunded;
133	    }
134	
135	    private String formatMoney(double value) {
136	        return String.format("%.2f", value).replace(",", ".");
137	    }
