127	    }
128	
129	    private double calculateAmountForRevenue(Reservation res) {
130	        double paid = res.amountPaid;
131	        double refunded = res.refund != null ? res.refund : 0;
132	        return paid - refunded;
133	    }
134	
135	    private String formatMoney(double value) {
136	        return String.format("%.2f", value).replace(",", ".");
137	    }
138	}
